@page "/dashboard"
@inject Services.WarehouseState WarehouseState
@inject Services.InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard - @WarehouseState.SelectedWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-header">
        <strong>@WarehouseState.SelectedWarehouseName</strong> — Overview
    </div>
    <div class="card-body">
        <div class="row">
            <div class="col-md-4">
                <div class="card text-center">
                    <div class="card-body">
                        <h5 class="card-title">Low Stock Alerts</h5>
                        <p class="display-4">
                            <AlertBadge StartPolling="true" />
                        </p>
                        <p class="text-muted">Items below minimum level</p>
                        <p class="small text-muted">Auto-refreshes every 10 seconds</p>
                    </div>
                </div>
            </div>
            <div class="col-md-4">
                <div class="card text-center">
                    <div class="card-body">
                        <h5 class="card-title">Current Site</h5>
                        <p class="display-6">@WarehouseState.SelectedWarehouseName</p>
                        <p class="text-muted">Selected warehouse</p>
                    </div>
                </div>
            </div>
            <div class="col-md-4">
                <div class="card text-center">
                    <div class="card-body">
                        <h5 class="card-title">Last Checked</h5>
                        <p class="display-6">@_lastChecked</p>
                        <p class="text-muted">Most recent poll time</p>
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    private string _lastChecked = "—";
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        _alertHandler = () => InvokeAsync(() =>
        {
            _lastChecked = DateTime.Now.ToString("HH:mm:ss");
            StateHasChanged();
        });
        _warehouseHandler = () => InvokeAsync(StateHasChanged);

        AlertService.OnAlertCountChanged += _alertHandler;
        WarehouseState.OnChange += _warehouseHandler;
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= _alertHandler;
        WarehouseState.OnChange -= _warehouseHandler;
    }
}

